CREATE TABLE demo_stock(id INTEGER PRIMARY KEY,qty INTEGER NOT NULL CHECK(qty>=0));
CREATE TABLE shipment(id INTEGER PRIMARY KEY,qty INTEGER NOT NULL);
INSERT INTO demo_stock VALUES(1,20);
BEGIN TRANSACTION;
UPDATE demo_stock SET qty=qty-5 WHERE id=1;
INSERT INTO shipment VALUES(1,5);
ROLLBACK;
SELECT qty,(SELECT COUNT(*) FROM shipment) AS shipments FROM demo_stock WHERE id=1;

